// frontend/src/components/Sidebar.jsx
import React from "react";
import { Link, useNavigate } from "react-router-dom";
import "./Sidebar.css";

export default function Sidebar({ sessions = [], onLoadSession = () => {}, onNewChat = () => {} }) {
  const navigate = useNavigate();

  const handleNewChat = () => {
    onNewChat();
    navigate("/"); // go to home-page (chat)
  };

  return (
    <aside className="sidebar">
      <button className="btn-new-chat" onClick={handleNewChat}>
        + New Chat
      </button>

      <div className="sidebar-section">
        <div className="sidebar-title">Chat History</div>

        <div className="session-list">
          {sessions.length === 0 && <div className="empty">No chats yet.</div>}

          {sessions.map((s) => (
            <div
              key={s.id}
              className="session-item"
              onClick={() => {
                onLoadSession(s);
                navigate("/");
              }}
            >
              {s.title}
            </div>
          ))}
        </div>
      </div>

      <div className="sidebar-section">
        <div className="sidebar-title">Navigation</div>

        {/* ❌ Home removed */}
        {/* <Link to="/" className="nav-item">🏠 Home</Link> */}

        <Link to="/flights" className="nav-item">
          ✈️ Flight Search
        </Link>

        <Link to="/hotels" className="nav-item">
          🏨 Hotels & Cuisines
        </Link>

        <Link to="/news" className="nav-item">
          📰 Travel News & Blogs
        </Link>
      </div>

      <div className="sidebar-user">
        <div className="user-avatar">👤</div>
        <div className="user-email">harsh@example.com</div>
      </div>
    </aside>
  );
}
